<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('salary_advance.view_own');verify_csrf();$pdo=staff_db();$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'&&can('salary_advance.submit')){$s=$pdo->prepare("INSERT INTO salary_advances(staff_id,amount,reason,repayment_notes) VALUES(?,?,?,?)");$s->execute([$staff['id'],$_POST['amount'],trim($_POST['reason']),trim($_POST['repayment_notes']??'')?:null]);flash('success','Request submitted.');staff_redirect('staff/pages/salary-advance.php');}
$s=$pdo->prepare("SELECT r.*,r.reason detail FROM salary_advances r WHERE r.staff_id=? ORDER BY r.created_at DESC");$s->execute([$staff['id']]);$rows=$s->fetchAll();
$pageTitle='Salary Advance';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Requests</p><h1>Salary Advance</h1></div></div><div class="split-grid"><section class="staff-panel"><h2>New request</h2><form method="post"><?= csrf_field() ?>
    <label>Amount (RM)<input type="number" step=".01" name="amount" required></label><label>Reason<textarea name="reason" required></textarea></label><label>Repayment notes<textarea name="repayment_notes"></textarea></label>
    <button class="btn primary">Submit request</button></form></section><section class="staff-panel table-panel"><h2>My requests</h2><table><thead><tr><th>Details</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= h($r['detail']??$r['reason']??'') ?></td><td><span class="pill <?= h($r['status']) ?>"><?= h($r['status']) ?></span></td><td><?= h(date('j M Y',strtotime($r['created_at']))) ?></td></tr><?php endforeach;?></tbody></table></section></div></main><?php require __DIR__.'/../../includes/staff/footer.php';?>